urllib3.util.url.parse_url:
def parse_url(url: str) -> Url:
    """
    Given a url, return a parsed :class:`.Url` namedtuple. Best-effort is
    performed to parse incomplete urls. Fields not provided will be None.
    This parser is RFC 3986 and RFC 6874 compliant.

    The parser logic and helper functions are based heavily on
    work done in the ``rfc3986`` module.

    :param str url: URL to parse into a :class:`.Url` namedtuple.

    Partly backwards-compatible with :mod:`urllib.parse`.

    Example:

    .. code-block:: python

        import urllib3

        print( urllib3.util.parse_url('http://google.com/mail/'))
        # Url(scheme='http', host='google.com', port=None, path='/mail/', ...)

        print( urllib3.util.parse_url('google.com:80'))
        # Url(scheme=None, host='google.com', port=80, path=None, ...)

        print( urllib3.util.parse_url('/foo?bar'))
        # Url(scheme=None, host=None, port=None, path='/foo', query='bar', ...)
    """
    if not url:
        return Url()
    source_url = url
    if not _SCHEME_RE.search(url):
        url = '//' + url
    scheme: str | None
    authority: str | None
    auth: str | None
    host: str | None
    port: str | None
    port_int: int | None
    path: str | None
    query: str | None
    fragment: str | None
    try:
        (scheme, authority, path, query, fragment) = _URI_RE.match(url).groups()
        normalize_uri = (scheme is None or scheme.lower() in _NORMALIZABLE_SCHEMES)
        if scheme:
            scheme = scheme.lower()
        if authority:
            (auth, _, host_port) = authority.rpartition('@')
            auth = (auth or None)
            (host, port) = _HOST_PORT_RE.match(host_port).groups()
            if (auth and normalize_uri):
                auth = _encode_invalid_chars(auth, _USERINFO_CHARS)
            if port == '':
                port = None
        else:
            (auth, host, port) = (None, None, None)
        if port is not None:
            port_int = int(port)
            if not 0 <= port_int <= 65535:
                raise LocationParseError(url)
        else:
            port_int = None
        host = _normalize_host(host, scheme)
        if (normalize_uri and path):
            path = _remove_path_dot_segments(path)
            path = _encode_invalid_chars(path, _PATH_CHARS)
        if (normalize_uri and query):
            query = _encode_invalid_chars(query, _QUERY_CHARS)
        if (normalize_uri and fragment):
            fragment = _encode_invalid_chars(fragment, _FRAGMENT_CHARS)
    except (ValueError, AttributeError) as e:
        raise LocationParseError(source_url) from e
    if not path:
        if (query is not None or fragment is not None):
            path = ''
        else:
            path = None
    return Url(scheme=scheme, auth=auth, host=host, port=port_int, path=path, query=query, fragment=fragment)

urllib3.util.url._remove_path_dot_segmen:
def _remove_path_dot_segments(path: str) -> str:
    segments = path.split('/')
    output = []
    for segment in segments:
        if segment == '.':
            continue
        if segment != '..':
            output.append(segment)
        elif output:
            output.pop()
    if (path.startswith('/') and ((not output or output[0]))):
        output.insert(0, '')
    if path.endswith(('/.', '/..')):
        output.append('')
    return '/'.join(output)

urllib3.util.url._normalize_host:
def _normalize_host(host: str | None, scheme: str | None) -> str | None:
    if host:
        if scheme in _NORMALIZABLE_SCHEMES:
            is_ipv6 = _IPV6_ADDRZ_RE.match(host)
            if is_ipv6:
                match = _ZONE_ID_RE.search(host)
                if match:
                    (start, end) = match.span(1)
                    zone_id = host[start:end]
                    if (zone_id.startswith('%25') and zone_id != '%25'):
                        zone_id = zone_id[3:]
                    else:
                        zone_id = zone_id[1:]
                    zone_id = _encode_invalid_chars(zone_id, _UNRESERVED_CHARS)
                    return f'{host[:start].lower()}%{zone_id}{host[end:]}'
                else:
                    return host.lower()
            elif not _IPV4_RE.match(host):
                return to_str(b'.'.join([_idna_encode(label) for label in host.split('.')]), 'ascii')
    return host

urllib3.contrib.emscripten.fetch.send_st:
def send_streaming_request(request: EmscriptenRequest) -> EmscriptenResponse | None:
    if has_jspi():
        return send_jspi_request(request, True)
    elif is_in_node():
        raise _RequestError(message=NODE_JSPI_ERROR, request=request, response=None)
    if (_fetcher and streaming_ready()):
        return _fetcher.send(request)
    else:
        _show_streaming_warning()
        return None

urllib3.contrib.emscripten.fetch.streami:
def streaming_ready() -> bool | None:
    if _fetcher:
        return _fetcher.streaming_ready
    else:
        return None

urllib3.util.wait.poll_wait_for_socket:
def poll_wait_for_socket(sock: socket.socket, read: bool = False, write: bool = False, timeout: float | None = None) -> bool:
    if (not read and not write):
        raise RuntimeError('must specify at least one of read=True, write=True')
    mask = 0
    if read:
        mask |= select.POLLIN
    if write:
        mask |= select.POLLOUT
    poll_obj = select.poll()
    poll_obj.register(sock, mask)

    def do_poll(t: float | None) -> list[tuple[(int, int)]]:
        if t is not None:
            t *= 1000
        return poll_obj.poll(t)
    return bool(do_poll(timeout))

urllib3.util.wait.wait_for_socket:
def wait_for_socket(sock: socket.socket, read: bool = False, write: bool = False, timeout: float | None = None) -> bool:
    global wait_for_socket
    if _have_working_poll():
        wait_for_socket = poll_wait_for_socket
    elif hasattr(select, 'select'):
        wait_for_socket = select_wait_for_socket
    return wait_for_socket(sock, read, write, timeout)

urllib3.util.wait._have_working_poll:
def _have_working_poll() -> bool:
    try:
        poll_obj = select.poll()
        poll_obj.poll(0)
    except (AttributeError, OSError):
        return False
    else:
        return True

urllib3.util.wait.select_wait_for_socket:
def select_wait_for_socket(sock: socket.socket, read: bool = False, write: bool = False, timeout: float | None = None) -> bool:
    if (not read and not write):
        raise RuntimeError('must specify at least one of read=True, write=True')
    rcheck = []
    wcheck = []
    if read:
        rcheck.append(sock)
    if write:
        wcheck.append(sock)
    fn = partial(select.select, rcheck, wcheck, wcheck)
    (rready, wready, xready) = fn(timeout)
    return bool((rready or wready or xready))

urllib3.util.util.to_str:
def to_str(x: str | bytes, encoding: str | None = None, errors: str | None = None) -> str:
    if isinstance(x, str):
        return x
    elif not isinstance(x, bytes):
        raise TypeError(f'not expecting type {type(x).__name__}')
    if (encoding or errors):
        return x.decode((encoding or 'utf-8'), errors=(errors or 'strict'))
    return x.decode()

urllib3.util.url._idna_encode:
def _idna_encode(name: str) -> bytes:
    if not name.isascii():
        try:
            import idna
        except ImportError:
            raise LocationParseError("Unable to parse URL without the 'idna' module") from None
        try:
            return idna.encode(name.lower(), strict=True, std3_rules=True)
        except idna.IDNAError:
            raise LocationParseError(f"Name '{name}' is not a valid IDNA label") from None
    return name.lower().encode('ascii')

urllib3.util.ssl_match_hostname.match_ho:
def match_hostname(cert: _TYPE_PEER_CERT_RET_DICT | None, hostname: str, hostname_checks_common_name: bool = False) -> None:
    """Verify that *cert* (in decoded format as returned by
    SSLSocket.getpeercert()) matches the *hostname*.  RFC 2818 and RFC 6125
    rules are followed, but IP addresses are not accepted for *hostname*.

    CertificateError is raised on failure. On success, the function
    returns nothing.
    """
    if not cert:
        raise ValueError('empty or no certificate, match_hostname needs a SSL socket or SSL context with either CERT_OPTIONAL or CERT_REQUIRED')
    try:
        if '%' in hostname:
            host_ip = ipaddress.ip_address(hostname[:hostname.rfind('%')])
        else:
            host_ip = ipaddress.ip_address(hostname)
    except ValueError:
        host_ip = None
    dnsnames = []
    san: tuple[(tuple[(str, str)], ...)] = cert.get('subjectAltName', ())
    key: str
    value: str
    for (key, value) in san:
        if key == 'DNS':
            if (host_ip is None and _dnsname_match(value, hostname)):
                return
            dnsnames.append(value)
        elif key == 'IP Address':
            if (host_ip is not None and _ipaddress_match(value, host_ip)):
                return
            dnsnames.append(value)
    if (hostname_checks_common_name and host_ip is None and not dnsnames):
        for sub in cert.get('subject', ()):
            for (key, value) in sub:
                if key == 'commonName':
                    if _dnsname_match(value, hostname):
                        return
                    dnsnames.append(value)
    if len(dnsnames) > 1:
        raise CertificateError("hostname %r doesn't match either of %s" % (hostname, ', '.join(map(repr, dnsnames))))
    elif len(dnsnames) == 1:
        raise CertificateError(f"hostname {hostname!r} doesn't match {dnsnames[0]!r}")
    else:
        raise CertificateError('no appropriate subjectAltName fields were found')

urllib3.util.ssl_match_hostname._dnsname:
def _dnsname_match(dn: typing.Any, hostname: str, max_wildcards: int = 1) -> typing.Match[str] | None | bool:
    """Matching according to RFC 6125, section 6.4.3

    http://tools.ietf.org/html/rfc6125#section-6.4.3
    """
    pats = []
    if not dn:
        return False
    parts = dn.split('.')
    leftmost = parts[0]
    remainder = parts[1:]
    wildcards = leftmost.count('*')
    if wildcards > max_wildcards:
        raise CertificateError('too many wildcards in certificate DNS name: ' + repr(dn))
    if not wildcards:
        return bool(dn.lower() == hostname.lower())
    if leftmost == '*':
        pats.append('[^.]+')
    elif (leftmost.startswith('xn--') or hostname.startswith('xn--')):
        pats.append(re.escape(leftmost))
    else:
        pats.append(re.escape(leftmost).replace('\\*', '[^.]*'))
    for frag in remainder:
        pats.append(re.escape(frag))
    pat = re.compile('\\A' + '\\.'.join(pats) + '\\Z', re.IGNORECASE)
    return pat.match(hostname)
